// Nạp biến môi trường từ file .env
require('dotenv').config();

// Biến đếm initCount: Chạy ngay khi module được nạp lần đầu tiên (khi có lệnh require đầu tiên)
let initCount = 0;
initCount++;
console.log(`[LOGGER MODULE LOADED] initCount hiện tại: ${initCount}`);

// Định nghĩa mức độ ưu tiên của log (info < warn < error)
const LOG_LEVELS = {
    info: 1,
    warn: 2,
    error: 3
};

// Đọc LOG_LEVEL từ biến môi trường, mặc định là 'info' nếu không cấu hình
const currentEnvLevel = process.env.LOG_LEVEL ? process.env.LOG_LEVEL.toLowerCase() : 'info';
const minLevelValue = LOG_LEVELS[currentEnvLevel] || LOG_LEVELS.info;

// Các hàm log với cơ chế kiểm tra mức ưu tiên
function info(msg) {
    if (LOG_LEVELS.info >= minLevelValue) {
        console.log(`[INFO] ${msg}`);
    }
}

function warn(msg) {
    if (LOG_LEVELS.warn >= minLevelValue) {
        console.warn(`[WARN] ${msg}`);
    }
}

function error(msg) {
    if (LOG_LEVELS.error >= minLevelValue) {
        console.error(`[ERROR] ${msg}`);
    }
}

// Lấy giá trị initCount hiện tại
function getInitCount() {
    return initCount;
}

// Export các hàm và hàm lấy initCount theo chuẩn CommonJS
module.exports = {
    info,
        warn,
        error,
        getInitCount
};